n = int(input()) 
danhsach = {} 
for i in range(1,n+1): 
    ID = f'TS0{str(i)}'
    hovaten = input() 
    diem1 = float(input()) 
    diem2 = float(input()) 
    if diem1 > 10: 
        diem1 = diem1 /10 
    if diem2 > 10: 
        diem2 = diem2 /10 
    average = (diem1+diem2)/2 
    rank = None 
    if average < 5.0: 
        rank = 'TRUOT' 
    elif 5.0 <= average < 8.0: 
        rank = 'CAN NHAC'
    elif 8.0 <= average < 9.5: 
        rank = 'DAT' 
    elif average >= 9.5: 
        rank = 'XUAT SAC'
    danhsach[ID] = [hovaten, average, rank] 
danhsachsapxep = dict(sorted(danhsach.items(), key =lambda x: x[1][1], reverse = True))
for vanh1 in danhsachsapxep: 
    hovaten, average,rank = danhsachsapxep[vanh1]
    print(vanh1, hovaten, f"{average:.2f}", rank)

